import{d as g,C as t,o as d,c as h,a3 as e,E as i,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三章","description":"《正易心法》第三章——卦象视人，本无文字：羲皇不立文字，使天下嘿观其象；顺象则吉凶自应，违象则吉凶反。开篇三章至此完成认识论建构。","frontmatter":{"title":"正易心法·第三章","description":"《正易心法》第三章——卦象视人，本无文字：羲皇不立文字，使天下嘿观其象；顺象则吉凶自应，违象则吉凶反。开篇三章至此完成认识论建构。","category":"guide","aliases":["正易心法第三章","卦象视人本无文字","不言之教"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-03.md","filePath":"yijing/zheng-yi-xin-fa/chapter-03.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-03.md"},x=g({...c,setup(u){const s=[{id:"z3-01",label:"一、卦象视人",showLabel:!0,sentences:[["卦象",{text:"视人",glossary:"shiRen"},"，本无文字，使人",{text:"消息",glossary:"xiaoxi"},"，吉凶",{text:"嘿会",glossary:"moHui"},"。"]],note:["卦象是展示给人看的，本来没有文字；它让人体察阴阳消长，默默领会吉凶。（「视」通「示」，是展示、告示之义；「嘿」同「默」。这一句是本章的总纲：卦画本身即为表达，不假文字。）"]},{id:"z3-02",label:"二、嘿观其象",showLabel:!0,sentences:[["羲皇始画八卦，重为六十四，不立文字，使天下之人",{text:"嘿观",glossary:"moGuan"},"其象而已。"]],note:["伏羲最初画八卦，重叠为六十四卦，不立任何文字，只是让天下之人默默观察卦象而已。（静默观象、内心体悟，是伏羲的教法；文字是后来才加上去的一层。）"]},{id:"z3-03",label:"三、如象与违象",showLabel:!0,sentences:[["能",{text:"如象",glossary:"ruXiang"},"焉，则吉凶应；",{text:"违其象",glossary:"weiXiang"},"，则吉凶反。"]],note:["能够顺应卦象之理而行，则吉凶如期应验；违背卦象之理，则吉凶反转。这里的「吉凶应」不是趋吉避凶的算计，而是说：卦象本身就是天道运行的写照，顺之则人与天道合一，自然感应；违之则人与天道割裂，感应失灵。"]},{id:"z3-04",label:"四、不言之教",showLabel:!0,sentences:[["此羲皇氏作",{text:"不言之教",glossary:"buyanZhijiao"},"也。"]],note:["这就是伏羲氏所创的「不言之教」。（这四个字直接来自《老子》「行不言之教」——麻衣把它从老子移给了伏羲：卦象就是道的显现，道不可言，所以卦象本无文字。这一嫁接，正显出陈抟一脉以道解易的底色。）"]},{id:"z3-05",label:"五、郑康成略知此说",showLabel:!0,sentences:[[{text:"郑康成",glossary:"zhengKangcheng"},{text:"略知",glossary:"lvezhi"},"此说。"]],note:["郑康成（郑玄）对此略有所知。这是本章分量最重的一句：看似轻描淡写，实则是「已知门在何处，却仍留在门外」的评语——郑玄重卦气说，知道卦与天道节律相应，但仍以训诂文字的方式治《易》，所以说「略知」。"]}],o=[{id:"shiRen",term:"视人",pinyin:"shì rén",meaning:"示人、给人看。「视」在此通「示」，是展示、告示之义。"},{id:"xiaoxi",term:"消息",pinyin:"xiāo xī",meaning:"阴阳消长。同第一章用法，指体察阴阳进退之理。"},{id:"moHui",term:"嘿会",pinyin:"mò huì",meaning:"嘿同「默」，默默领会。不需文字说明而心中自会。"},{id:"moGuan",term:"嘿观",pinyin:"mò guān",meaning:"默默观察。静默观象、内心体悟，是伏羲的教法。"},{id:"ruXiang",term:"如象",pinyin:"rú xiàng",meaning:"顺应卦象。行为与卦象所示之理相符。"},{id:"weiXiang",term:"违其象",pinyin:"wéi qí xiàng",meaning:"违背卦象。行为与卦象所示之理相悖。"},{id:"buyanZhijiao",term:"不言之教",pinyin:"bù yán zhī jiào",meaning:"《老子》「行不言之教」，指无需语言文字的教化方式。麻衣以此说伏羲画卦。"},{id:"zhengKangcheng",term:"郑康成",pinyin:"zhèng kāng chéng",meaning:"郑玄（127—200），字康成，东汉经学大师，遍注群经。其易学重卦气说，即卦与节气、月令的对应。"},{id:"lvezhi",term:"略知",pinyin:"lüè zhī",meaning:"略微知晓。言下之意：知而未尽，仅得皮毛——摸到了门边，却仍留在文字功夫里。"}];return(b,n)=>{const r=t("DaoTextReading"),l=t("DaoKeywordCards");return d(),h("div",null,[n[0]||(n[0]=e("",20)),i(r,{colophon:"本无文字 · 嘿观其象 · 如象违象 · 不言之教",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三章原文",sections:s,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（如「嘿」同「默」、「视」通「示」），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(l,{items:[{term:"视人",pinyin:["shì","rén"],meaning:"示人、给人看。「视」在此通「示」，是展示、告示之义。"},{term:"嘿观",pinyin:["mò","guān"],meaning:"默默观察。静默观象、内心体悟，是伏羲的教法。"},{term:"如象 / 违其象",pinyin:["rú","xiàng"],meaning:"顺应卦象则吉凶应；违背卦象则吉凶反。卦象即天道之写照，顺之则合一，违之则割裂。"},{term:"不言之教",pinyin:["bù","yán"],meaning:"《老子》「行不言之教」。麻衣移之于伏羲：卦象即道，道不可言，故卦象本无文字。"},{term:"郑康成",pinyin:["zhèng","kāng","chéng"],meaning:"郑玄（127—200），字康成，东汉经学大师。重卦气说——知卦与天道相应，但仍以训诂治《易》，故云「略知」。"}]}),n[3]||(n[3]=e("",23))])}}});export{y as __pageData,x as default};
